use super::*;
use crate::fiscal_repository::{Repository,Policy,Clock,ActivationIntent};
use std::{path::{Path,PathBuf},fs,sync::Mutex,time::Duration};
use nomina_fiscal_package::{wire::Capability,hashes,canonical};
fn id()->String{uuid::Uuid::new_v4().to_string()}
fn fixture(n:&str)->Vec<u8>{fs::read(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b2/fixtures").join(n)).unwrap()}
struct Qa{root:PathBuf,service:Arc<ExecutionService>,owner:Owner,time:Arc<Mutex<String>>}
impl Qa{
 fn new()->Self{Self::package("package1.nomina-fiscal",false)}
 fn package(file:&str,direct:bool)->Self{let root=std::env::temp_dir().join("opencode").join(format!("5b7-5d3b2-4c-{}",id()));let time=Arc::new(Mutex::new("2026-10-28T12:00:00Z".into()));let repo=Repository::new(root.clone(),Policy::import_qa()).execution_test_clock(Clock{fixed:Some(time.clone())});repo.initialize_new().unwrap();repo.accept_trust_episode(&id(),0,&[fixture("trust.json")]).unwrap();let mut g=1;if direct{repo.accept_trust_episode(&id(),1,&[fixture("trust-direct.json")]).unwrap();g=2;}let iid=repo.record_verified_installation(&id(),g,&fixture(file),if direct{&[Capability::Direct]}else{&[Capability::Direct,Capability::Inverse]}).unwrap().installation_id.unwrap();let p=repo.prepare_activation(ActivationIntent::Admit,Some(&iid),None,None).unwrap();repo.confirm_activation(&id(),&p).unwrap();let select=repo.prepare_activation(ActivationIntent::Select,Some(&iid),p.admission_id.as_deref(),None).unwrap();repo.confirm_activation(&id(),&select).unwrap();let imports=Arc::new(ImportService::new(repo,true));let owner=imports.owner("main",90).unwrap();Self{root,service:Arc::new(ExecutionService::new(imports)),owner,time}}
 fn request(&self)->PrepareRequest{let selected=self.service.imports.repository.selection_status().unwrap().selection;PrepareRequest{client_request_id:id(),request_id:1,expected_selection_id:selected.id.unwrap(),expected_selection_generation:selected.generation,capture:Capture{area:"general-zone".into(),form:Form{mode:"gross-to-net".into(),amount:"15000.50".into(),period:"monthly".into(),effective_date:"2026-02-01".into(),bonus_days:"15".into(),vacation_days:"12".into(),vacation_premium:"25".into(),include_imss:true}},scenario:serde_json::json!({"kind":"contextual-retention-2026-v2","salaryBasis":"fixed-period","monthlyCondition":"unknown","referenceMonth":"2026-02"})}}
 fn reference(s:&State)->ReferenceRequest{ReferenceRequest{handle:Some(s.handle.clone()),client_request_id:None}}
 fn install_b(&self){let repo=&self.service.imports.repository;let g=repo.open_existing().unwrap().generation;let iid=repo.record_verified_installation(&id(),g,&fixture("package2.nomina-fiscal"),&[Capability::Direct,Capability::Inverse]).unwrap().installation_id.unwrap();let p=repo.prepare_activation(ActivationIntent::Admit,Some(&iid),None,None).unwrap();repo.confirm_activation(&id(),&p).unwrap();let p=repo.prepare_activation(ActivationIntent::Select,Some(&iid),p.admission_id.as_deref(),None).unwrap();repo.confirm_activation(&id(),&p).unwrap();}
 fn update(&self,n:&str){let repo=&self.service.imports.repository;let g=repo.open_existing().unwrap().generation;repo.accept_trust_episode(&id(),g,&[fixture(n)]).unwrap();}
}
impl Drop for Qa{fn drop(&mut self){let _=fs::remove_dir_all(&self.root);}}
#[test]fn real_native_session_binds_exact_capture_material_hashes_and_seven_sets(){let q=Qa::new();let r=q.request();let before=q.service.imports.repository.open_existing().unwrap().generation;let s=q.service.prepare(&q.owner,&r).unwrap();assert_eq!(s.phase,"ready");let body=q.service.material(&q.owner,&Qa::reference(&s)).unwrap();assert_eq!(hashes::sha256(body.as_bytes()),s.material_sha256.unwrap());let v:serde_json::Value=serde_json::from_str(&body).unwrap();assert_eq!(v["capture"],serde_json::to_value(&r.capture).unwrap());assert_eq!(v["context"]["effectiveSets"].as_array().unwrap().len(),7);assert_eq!(canonical::bytes(&v["packageEnvelope"]).unwrap(),fixture("package1.nomina-fiscal"));assert_eq!(q.service.imports.repository.open_existing().unwrap().generation,before);assert!(!s.persistence_allowed&&!s.mathematical_attestation);}
#[test]fn install_and_select_b_does_not_replace_issued_a_material(){let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();let before=q.service.material(&q.owner,&Qa::reference(&s)).unwrap().to_string();q.install_b();assert_eq!(q.service.material(&q.owner,&Qa::reference(&s)).unwrap().to_string(),before);let b=q.service.prepare(&q.owner,&q.request()).unwrap();let after=q.service.material(&q.owner,&Qa::reference(&b)).unwrap().to_string();assert_ne!(before,after);assert_ne!(s.context_sha256,b.context_sha256);}
#[test]fn inverse_a_can_continue_after_selecting_b(){let q=Qa::new();let mut r=q.request();r.capture.form.mode="net-to-gross".into();r.capture.form.amount="13202.64".into();let s=q.service.prepare(&q.owner,&r).unwrap();assert_eq!(s.phase,"ready");q.install_b();assert_eq!(q.service.status(&q.owner,&Qa::reference(&s)).unwrap().phase,"ready");}
#[test]fn duplicate_prepare_is_idempotent_but_request_swap_conflicts(){let q=Qa::new();let mut r=q.request();let a=q.service.prepare(&q.owner,&r).unwrap();assert_eq!(q.service.prepare(&q.owner,&r).unwrap().execution_id,a.execution_id);r.capture.form.amount="16000.00".into();assert_eq!(q.service.prepare(&q.owner,&r).unwrap_err().code,"REQUEST_CONFLICT");}
#[test]fn unknown_handle_and_other_owner_cannot_read_material(){let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();let mut other=q.owner.clone();other.incarnation=id();assert_eq!(q.service.material(&other,&Qa::reference(&s)).unwrap_err().code,"SESSION_OWNER_MISMATCH");assert!(q.service.material(&q.owner,&ReferenceRequest{handle:Some(id()),client_request_id:None}).is_err());}
#[test]fn cancellation_before_prepare_is_a_tombstone_for_late_callback(){let q=Qa::new();let r=q.request();assert_eq!(q.service.cancel(&q.owner,&ReferenceRequest{handle:None,client_request_id:Some(r.client_request_id.clone())}).unwrap_err().code,"CANCELLED_BEFORE_PREPARE");assert_eq!(q.service.prepare(&q.owner,&r).unwrap_err().code,"EXECUTION_CANCELLED");}
#[test]fn cancel_and_navigation_invalidate_owned_context_and_release_reservation(){let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();assert!(q.service.metrics().0>0);q.service.cancel(&q.owner,&Qa::reference(&s)).unwrap();assert_eq!(q.service.metrics().0,0);assert!(q.service.material(&q.owner,&Qa::reference(&s)).is_err());let s=q.service.prepare(&q.owner,&q.request()).unwrap();q.service.imports.navigation("main",true);q.service.navigation("main");q.service.imports.navigation("main",false);let next=q.service.imports.owner("main",90).unwrap();assert_eq!(q.service.material(&next,&Qa::reference(&s)).unwrap_err().code,"SESSION_OWNER_MISMATCH");assert_eq!(q.service.metrics().0,0);}
#[test]fn ttl_absolute_and_idle_are_monotonic_and_status_does_not_extend(){for(a,i)in [(600,0),(0,120)]{let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();q.service.age(&s.handle,Duration::from_secs(a),Duration::from_secs(i));assert_eq!(q.service.status(&q.owner,&Qa::reference(&s)).unwrap().phase,"expired");assert!(q.service.material(&q.owner,&Qa::reference(&s)).is_err());}}
#[test]fn capacity_reservations_bound_sessions_and_encoded_retention(){let q=Qa::new();let a=q.service.prepare(&q.owner,&q.request()).unwrap();let b=q.service.prepare(&q.owner,&q.request()).unwrap();assert_eq!(q.service.prepare(&q.owner,&q.request()).unwrap_err().code,"EXECUTION_CAPACITY");assert_eq!(q.service.metrics().0,a.material_bytes+b.material_bytes+4*RESULT_MAX+2*65536);assert!(q.service.metrics().1<=RETAINED_MAX);}
#[test]fn global_four_session_ceiling_and_peak_encoded_budget_survive_owner_changes(){let q=Qa::new();let request=q.request();q.service.prepare(&q.owner,&request).unwrap();q.service.prepare(&q.owner,&q.request()).unwrap();let other=q.service.imports.owner("main",91).unwrap();q.service.prepare(&other,&q.request()).unwrap();q.service.prepare(&other,&q.request()).unwrap();let next=q.service.imports.owner("main",92).unwrap();assert_eq!(q.service.prepare(&next,&q.request()).unwrap_err().code,"EXECUTION_CAPACITY");let(current,_,peak)=q.service.budget_metrics();assert!(current<=RETAINED_MAX&&peak<=RETAINED_MAX);fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4c/global-budget.json"),serde_json::to_vec_pretty(&serde_json::json!({"moduleQuotaTest":true,"retainedSessions":4,"fifthRejected":true,"encodedReservationBytes":current,"peakEncodedReservationBytes":peak,"limit":RETAINED_MAX,"notFourGuiWindows":true})).unwrap()).unwrap();}
#[test]fn direct_only_admission_cannot_authorize_inverse(){let q=Qa::package("package-direct.nomina-fiscal",true);let direct=q.service.prepare(&q.owner,&q.request()).unwrap();assert_eq!(direct.phase,"ready");let mut r=q.request();r.capture.form.mode="net-to-gross".into();let inverse=q.service.prepare(&q.owner,&r).unwrap();assert_eq!(inverse.reason.as_deref(),Some("OPERATION_NOT_ADMITTED"));}
#[test]fn revocation_blocks_prepared_authority_without_changing_frozen_observation(){let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();q.update("trust-revoked.json");let after=q.service.status(&q.owner,&Qa::reference(&s)).unwrap();assert_eq!(after.phase,"invalidated");assert!(q.service.material(&q.owner,&Qa::reference(&s)).is_err());assert_eq!(q.service.metrics().0,0);}
#[test]fn expiry_and_clock_rollback_block_pending_authority(){for now in ["2027-01-01T00:00:00Z","2026-10-25T00:00:00Z"]{let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();*q.time.lock().unwrap()=now.into();assert_eq!(q.service.status(&q.owner,&Qa::reference(&s)).unwrap().phase,"invalidated");}}
#[test]fn incompatible_dates_periods_and_frontend_authority_are_rejected(){let q=Qa::new();for key in ["date","period"]{let mut r=q.request();if key=="date"{r.capture.form.effective_date="2027-02-01".into();}else{r.capture.form.period="daily".into();}assert!(q.service.prepare(&q.owner,&r).is_err());}let mut v=serde_json::to_value(q.request()).unwrap();v["authorized"]=true.into();assert!(serde_json::from_value::<PrepareRequest>(v).is_err());}
#[test]fn transient_result_association_is_not_a_snapshot_or_execution_math_attestation(){let q=Qa::new();let r=q.request();let s=q.service.prepare(&q.owner,&r).unwrap();let originals:Vec<serde_json::Value>=serde_json::from_str(include_str!("../../../docs/evidence/5d2b/originals-v2.json")).unwrap();let old:serde_json::Value=serde_json::from_str(originals[0]["payload"].as_str().unwrap()).unwrap();let mut v=serde_json::json!({"capture":r.capture,"scenario":r.scenario,"contextSha256":s.context_sha256,"outcome":old["value"]["outcome"]});let req=CompleteRequest{handle:s.handle.clone(),result_wire:v.to_string()};let done=q.service.complete(&q.owner,&req).unwrap();assert_eq!(done.phase,"complete");assert!(!done.persistence_allowed&&!done.mathematical_attestation);assert_eq!(q.service.complete(&q.owner,&req).unwrap().result_sha256,done.result_sha256);v["outcome"]["report"]["gross"]["amount"]="16000.00".into();assert_eq!(q.service.complete(&q.owner,&CompleteRequest{handle:s.handle,result_wire:v.to_string()}).unwrap_err().code,"RESULT_CONFLICT");}
#[test]fn result_from_another_capture_or_context_is_not_accepted(){let q=Qa::new();let r=q.request();let s=q.service.prepare(&q.owner,&r).unwrap();let v=serde_json::json!({"capture":r.capture,"scenario":r.scenario,"contextSha256":"wrong","outcome":{}});assert_eq!(q.service.complete(&q.owner,&CompleteRequest{handle:s.handle,result_wire:v.to_string()}).unwrap_err().code,"RESULT_CONTEXT_MISMATCH");}
#[test]fn first_result_must_echo_the_authorized_amount_not_just_its_context_hash(){let q=Qa::new();let r=q.request();let s=q.service.prepare(&q.owner,&r).unwrap();let originals:Vec<serde_json::Value>=serde_json::from_str(include_str!("../../../docs/evidence/5d2b/originals-v2.json")).unwrap();let old:serde_json::Value=serde_json::from_str(originals[0]["payload"].as_str().unwrap()).unwrap();let mut v=serde_json::json!({"capture":r.capture,"scenario":r.scenario,"contextSha256":s.context_sha256,"outcome":old["value"]["outcome"]});v["outcome"]["report"]["gross"]["amount"]="16000.00".into();assert_eq!(q.service.complete(&q.owner,&CompleteRequest{handle:s.handle,result_wire:v.to_string()}).unwrap_err().code,"RESULT_CONTEXT_MISMATCH");}
#[test]fn restart_does_not_resurrect_ram_authority(){let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();let restarted=Arc::new(ExecutionService::new(q.service.imports.clone()));assert_eq!(restarted.status(&q.owner,&Qa::reference(&s)).unwrap_err().code,"SESSION_UNKNOWN");}
#[test]fn transient_json_is_bounded_and_duplicate_unicode_aliases_rejected(){assert!(json::parse(r#"{"a":1,"\u0061":2}"#).is_err());assert!(json::parse(&"[".repeat(100)).is_err());assert_eq!(json::parse(&" ".repeat(RESULT_MAX+1)).unwrap_err().code,"RESULT_TOO_LARGE");assert!(json::parse("-0").is_err());}
#[test]fn no_salary_or_result_is_written_into_fiscal_repository(){let q=Qa::new();let before=fs::read(q.root.join("fiscal/repository.sqlite3")).unwrap();let mut r=q.request();r.capture.form.amount="87654321.09".into();let s=q.service.prepare(&q.owner,&r).unwrap();q.service.material(&q.owner,&Qa::reference(&s)).unwrap();assert_eq!(fs::read(q.root.join("fiscal/repository.sqlite3")).unwrap(),before);assert!(!before.windows(11).any(|w|w==b"87654321.09"));}
#[test]fn normal_profile_never_emits_authority_or_creates_a_fiscal_database(){let root=std::env::temp_dir().join("opencode").join(format!("4c-prod-{}",id()));let service=ExecutionService::new(Arc::new(ImportService::new(Repository::new(root.clone(),Policy::production()),false)));assert_eq!(service.enabled().unwrap_err().code,"PRODUCTION_BOOTSTRAP_MISSING");assert!(!root.exists());}
#[test]fn transfer_permit_covers_serialization_and_encoded_memory_budget(){let q=Qa::new();let s=q.service.prepare(&q.owner,&q.request()).unwrap();let body=q.service.material(&q.owner,&Qa::reference(&s)).unwrap();let material_bytes=body.len();let wire_bytes=serde_json::to_vec(&body).unwrap().len();assert!(wire_bytes<=2*material_bytes+2);assert_eq!(q.service.material(&q.owner,&Qa::reference(&s)).unwrap_err().code,"MATERIAL_TRANSFER_BUSY");let(reserved,transfer,peak)=q.service.budget_metrics();assert_eq!(transfer,material_bytes*3+2);assert!(reserved+transfer<=RETAINED_MAX&&peak<=RETAINED_MAX);drop(body);assert_eq!(q.service.budget_metrics().1,0);let report=serde_json::json!({"encodedBudget":RETAINED_MAX,"sessionReservation":RESERVATION,"maximumSessions":4,"absoluteSeconds":600,"idleSeconds":120,"concurrentTransfers":1,"observedMaterialBytes":material_bytes,"observedJsonStringResponseBytes":wire_bytes,"observedReservedBytes":reserved,"observedTransferCharge":transfer,"observedPeakEncodedReservation":peak,"scope":"Encoded retained and transfer buffers, not a total heap guarantee"});fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4c/budgets.json"),serde_json::to_vec_pretty(&report).unwrap()).unwrap();}
